export const SUNDAY_ALLOWANCE_PENCE = 1250;

export function shiftPayPence(shift: Shift, ratePence: number): number {
    const pay = Math.round((paidMinutes(shift) * ratePence) / 60);
    // The allowance goes on after rounding, for a shift that starts on a Sunday.
    return weekdayOf(shift.day) === 6 ? pay + SUNDAY_ALLOWANCE_PENCE : pay;
}
